import type { BankQuestion } from "@/lib/bank";

/** Living World, Biological Classification and Plant Kingdom (Biology (NEET)): 90 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-living-world-plant-kingdom-1","question":"The five-kingdom system of classification was proposed in 1969 by:","options":["R. H. Whittaker","Carolus Linnaeus","Ernst Haeckel","H. F. Copeland"],"answer":0,"explanation":"R. H. Whittaker (1969) proposed Monera, Protista, Fungi, Plantae and Animalia, using cell structure, body organisation, mode of nutrition, reproduction and phylogeny. Linnaeus had given the two-kingdom system.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-2","question":"Which group of plants is called the 'amphibians of the plant kingdom'?","options":["Gymnosperms","Bryophytes","Green algae","Pteridophytes"],"answer":1,"explanation":"Bryophytes live on land but need water for sexual reproduction, since the antherozoids swim to the archegonium; hence the name.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-3","question":"Which is the lowest category in the taxonomic hierarchy?","options":["Species","Family","Order","Genus"],"answer":0,"explanation":"Species is the lowest (basic) taxonomic category; related species form a genus, genera a family, and families an order.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-4","question":"In the taxonomic hierarchy, the housefly (Musca domestica) belongs to the order:","options":["Diptera","Poales","Lepidoptera","Primata"],"answer":0,"explanation":"Housefly: class Insecta, order Diptera (two-winged flies). Primata is the order of man and Poales that of wheat.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-5","question":"Diatomaceous earth, used in polishing and filtration of oils and syrups, is formed from:","options":["The pellicle of euglenoids","The siliceous cell walls of diatoms (chrysophytes)","The calcareous shells of foraminiferans","The cellulose walls of dinoflagellates"],"answer":1,"explanation":"Diatoms have cell walls embedded with silica that are virtually indestructible; over billions of years these walls piled up as diatomaceous earth.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-6","question":"Red tides in the sea, caused by rapid multiplication of red dinoflagellates, are associated with the genus:","options":["Trypanosoma","Gonyaulax","Paramoecium","Euglena"],"answer":1,"explanation":"Red dinoflagellates such as Gonyaulax multiply so fast that the sea looks red; toxins they release may kill fish and other marine animals.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-7","question":"Viroids, discovered by T. O. Diener in 1971 as the cause of potato spindle tuber disease, differ from viruses in that viroids:","options":["Contain DNA as well as RNA","Have a protein coat but no nucleic acid","Are much larger than viruses","Are free RNA molecules lacking a protein coat"],"answer":3,"explanation":"A viroid is a free, low-molecular-weight RNA without the protein coat that viruses have; it is smaller than a virus. A protein without nucleic acid would be a prion, not a viroid.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-8","question":"Lichens are considered good indicators of air pollution because they:","options":["Fix atmospheric SO₂ into sulphates","Grow luxuriantly where SO₂ levels are high","Are found only in industrial areas","Do not grow in polluted areas"],"answer":3,"explanation":"Lichens (algae + fungi in symbiosis) are very sensitive to pollutants such as SO₂ and fail to grow in polluted areas, so their absence signals polluted air.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-9","question":"In Cycas the coralloid roots are associated with:","options":["Mycorrhizal fungi","Methanogenic archaebacteria","Nitrogen-fixing cyanobacteria","Nitrogen-fixing Rhizobium"],"answer":2,"explanation":"Specialised coralloid roots of Cycas harbour N₂-fixing cyanobacteria. The roots of Pinus, in contrast, have fungal associations (mycorrhiza).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-10","question":"Which statement about Mycoplasma is INCORRECT?","options":["Many are pathogenic in animals and plants","They can survive without oxygen","They are the smallest living cells known","They have a rigid peptidoglycan cell wall that gives them a fixed shape"],"answer":3,"explanation":"Mycoplasma completely lack a cell wall, which is why they have no fixed shape; they are the smallest known living cells and can survive without oxygen.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-11","question":"Which of the following fungi belongs to the Deuteromycetes (imperfect fungi)?","options":["Neurospora","Trichoderma","Albugo","Agaricus"],"answer":1,"explanation":"Deuteromycetes are fungi in which only the asexual or vegetative phase is known, e.g., Alternaria, Colletotrichum and Trichoderma. Agaricus is a basidiomycete, Neurospora an ascomycete and Albugo a phycomycete.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-12","question":"In basidiomycetes, sex organs are absent and plasmogamy is brought about by:","options":["Fusion of two vegetative or somatic cells of different strains or genotypes","Fusion of ascospores inside an ascus","Conjugation between two gametangia of the same strain","Fusion of a motile antherozoid with an egg"],"answer":0,"explanation":"In basidiomycetes plasmogamy occurs by fusion of somatic cells of different strains, giving a dikaryotic basidium in which karyogamy and meiosis produce four exogenous basidiospores.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-13","question":"Floridean starch, whose structure is very similar to amylopectin and glycogen, is the stored food of:","options":["Cyanobacteria","Chlorophyceae","Phaeophyceae","Rhodophyceae"],"answer":3,"explanation":"Red algae (Rhodophyceae) store floridean starch. Green algae store starch, while brown algae store laminarin or mannitol.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-14","question":"Which of the following pteridophytes are heterosporous, a feature regarded as a precursor to the seed habit?","options":["Selaginella and Salvinia","Equisetum and Dryopteris","Lycopodium and Pteris","Psilotum and Adiantum"],"answer":0,"explanation":"Selaginella and Salvinia produce two kinds of spores (macro- and microspores); the retention and germination of megaspores within the sporangium is a precursor to the seed habit. The others are homosporous.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-15","question":"Pinus has 2n = 24 chromosomes. The number of chromosomes in a cell of its endosperm is:","options":["48","12","36","24"],"answer":1,"explanation":"In gymnosperms the endosperm is the female gametophyte tissue, formed before fertilisation from the haploid megaspore, so it has n = 12. The triploid (3n) endosperm of angiosperms gives the trap answer 36.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-16","question":"Which alga shows a diplontic life cycle, in which the diploid sporophyte is dominant and the gametes are the only haploid phase?","options":["Volvox","Fucus","Spirogyra","Ectocarpus"],"answer":1,"explanation":"Fucus is diplontic, like all seed plants. Spirogyra and Volvox are haplontic, while Ectocarpus, Polysiphonia and kelps are haplo-diplontic.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-17","question":"Which statement about archaebacteria is correct?","options":["They are found only in moderate environments","Their cell wall is made of peptidoglycan exactly like that of eubacteria","Halophiles live in hot springs at very high temperatures","Methanogens present in the gut of ruminants produce methane (biogas) from their dung"],"answer":3,"explanation":"Methanogens live in the rumen of cows and buffaloes and produce methane. Archaebacteria have a cell wall structure different from other bacteria, survive harsh habitats, and it is thermoacidophiles, not halophiles, that live in hot springs.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-18","question":"Who described the infectious agent of tobacco mosaic disease as 'Contagium vivum fluidum' (infectious living fluid)?","options":["Dmitri Ivanowsky","T. O. Diener","M. W. Beijerinck","W. M. Stanley"],"answer":2,"explanation":"Beijerinck (1898) showed that the extract of infected tobacco leaves could infect healthy plants and called it Contagium vivum fluidum. Ivanowsky (1892) first recognised the agent as smaller than bacteria; Stanley (1935) crystallised the virus.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-19","question":"How many of the following statements about kingdom Monera are correct?\n(i) Cyanobacteria have chlorophyll a similar to green plants and are photosynthetic autotrophs.\n(ii) Nostoc and Anabaena fix atmospheric nitrogen in specialised cells called heterocysts.\n(iii) Chemosynthetic autotrophic bacteria oxidise inorganic substances such as nitrates, nitrites and ammonia to produce ATP.\n(iv) Bacteria reproduce mainly by fission and sometimes form spores under unfavourable conditions.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are NCERT statements. Bacteria also show a primitive form of DNA transfer from one bacterium to another, but reproduction is mainly by fission.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-20","question":"Match the protist group with its feature.\nList I: (A) Chrysophytes (B) Dinoflagellates (C) Euglenoids (D) Slime moulds\nList II: (1) Protein-rich pellicle in place of a cell wall (2) Spores with true walls dispersed by air currents (3) Two flagella, one longitudinal and one transverse in a furrow between the wall plates (4) Cell walls embedded with silica forming two thin overlapping shells","options":["A-3, B-4, C-2, D-1","A-4, B-1, C-3, D-2","A-4, B-3, C-1, D-2","A-2, B-3, C-1, D-4"],"answer":2,"explanation":"Diatoms (chrysophytes) have siliceous overlapping shells; dinoflagellates have two flagella lying in grooves between wall plates; euglenoids have a pellicle; slime mould fruiting bodies bear spores with true walls that are dispersed by air.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-21","question":"Assertion (A): In mosses the sporophyte is not free-living.\nReason (R): The sporophyte remains attached to the photosynthetic gametophyte and derives nourishment from it.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: the moss sporophyte (foot, seta, capsule) depends on the gametophyte for nutrition. In pteridophytes, by contrast, the sporophyte is the independent main plant body.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-22","question":"How many of the following statements about algae are correct?\n(i) Members of Chlorophyceae have chlorophyll a and b as their dominant pigments.\n(ii) Members of Phaeophyceae store food as floridean starch.\n(iii) Members of Rhodophyceae owe their red colour to r-phycoerythrin.\n(iv) Most red algae are freshwater forms found in cold regions.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Statements (i) and (iii) are correct. Brown algae store laminarin or mannitol (floridean starch belongs to red algae), and red algae are mostly marine, with greater concentration in warmer areas.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-23","question":"How many of the following statements about pteridophytes are correct?\n(i) The main plant body is a sporophyte differentiated into true root, stem and leaves.\n(ii) They are the first terrestrial plants to possess vascular tissues, xylem and phloem.\n(iii) The gametophyte, called a prothallus, is a small, multicellular, free-living, mostly photosynthetic thalloid structure.\n(iv) In Selaginella and Equisetum the sporophylls may form distinct compact structures called strobili or cones.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Pteridophytes still need water for fertilisation because the male gametes swim to the archegonium.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-24","question":"All of the following are members of the Phycomycetes EXCEPT:","options":["Claviceps","Mucor","Albugo","Rhizopus"],"answer":0,"explanation":"Mucor, Rhizopus (bread mould) and Albugo (parasite on mustard) are phycomycetes with aseptate, coenocytic mycelium. Claviceps, a source of ergot, is an ascomycete.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-25","question":"Match the taxonomic aid with its description.\nList I: (A) Key (B) Herbarium (C) Monograph (D) Flora\nList II: (1) Contains information on any one taxon (2) Actual account of the habitat and distribution of plants of a given area (3) Based on contrasting characters, generally in a pair called a couplet (4) Store-house of dried, pressed and preserved plant specimens on sheets","options":["A-1, B-4, C-3, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"A key uses couplets of contrasting characters; a herbarium stores pressed specimens on sheets; a monograph covers one taxon; a flora gives the habitat and distribution of plants of an area.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-26","question":"How many of the following statements are correct?\n(i) Viruses infecting plants generally have single-stranded RNA.\n(ii) Viruses infecting bacteria (bacteriophages) usually have double-stranded DNA.\n(iii) The protein coat of a virus is made of small subunits called capsomeres arranged in helical or polyhedral forms.\n(iv) Viroids are surrounded by a protein coat like viruses.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. Viroids are free RNA molecules that lack a protein coat.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-27","question":"How many of the following statements about gymnosperms are correct?\n(i) Gymnosperms are heterosporous, producing haploid microspores and megaspores.\n(ii) In Cycas, male cones and megasporophylls are borne on the same tree.\n(iii) The giant redwood tree Sequoia is one of the tallest tree species.\n(iv) Conifers have needle-like leaves with a thick cuticle and sunken stomata that reduce water loss.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (iii) and (iv) are correct. Cycas is dioecious, with male cones and megasporophylls on different trees; in Pinus both are borne on the same tree.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-28","question":"Assertion (A): Slime moulds are saprophytic protists.\nReason (R): Under unfavourable conditions the plasmodium forms fruiting bodies bearing spores that have true walls and can survive for many years.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both are true, but R describes how slime moulds survive bad conditions, not why they are saprophytic. They are saprophytic because the body moves along decaying twigs and leaves engulfing organic material.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-29","question":"How many of the following statements about binomial nomenclature are correct?\n(i) Biological names are generally in Latin and written in italics.\n(ii) The first word denotes the genus and the second the specific epithet.\n(iii) When handwritten, the two words are underlined together by one continuous line.\n(iv) Both the genus name and the specific epithet start with a capital letter.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (ii) are correct. Handwritten names are underlined separately, and only the genus name starts with a capital letter; the specific epithet starts with a small letter.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-30","question":"Match the algal product with its source.\nList I: (A) Algin (B) Carrageen (C) Agar (D) Protein-rich food supplement used even by space travellers\nList II: (1) Gelidium and Gracilaria (2) Chlorella (3) Red algae (4) Brown algae","options":["A-1, B-3, C-4, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2"],"answer":3,"explanation":"Brown algae yield the hydrocolloid algin and red algae yield carrageen; agar, used in culture media, comes from Gelidium and Gracilaria; unicellular Chlorella is a protein-rich food supplement.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-31", "question": "In bryophytes, the main plant body is:", "options": ["The haploid gametophyte", "The diploid sporophyte", "A diploid protonema", "A triploid thallus"], "answer": 0, "explanation": "The dominant, independent plant body of a bryophyte is the haploid gametophyte; the diploid sporophyte stays attached to it and depends on it.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-32", "question": "Which fungus is used extensively in biochemical and genetic work?", "options": ["Albugo", "Neurospora", "Puccinia", "Ustilago"], "answer": 1, "explanation": "Neurospora, an ascomycete, is a classic organism for biochemical and genetic studies. Albugo is a parasitic phycomycete, and Puccinia and Ustilago are rust and smut fungi.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-33", "question": "In plant taxonomy, the abbreviation ICBN stands for:", "options": ["International Committee of Biological Naming", "Indian Council of Botanical Names", "International Code for Botanical Nomenclature", "International Code for Bacterial Nomenclature"], "answer": 2, "explanation": "Scientific names of plants follow the International Code for Botanical Nomenclature (ICBN); animals follow the ICZN.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-34", "question": "In mosses, the protonema stage of the gametophyte develops directly from:", "options": ["A gemma", "A zygote", "A secondary branch of the leafy stage", "A spore"], "answer": 3, "explanation": "The moss spore germinates into the creeping, green, filamentous protonema; the leafy stage then develops from it as a lateral bud. Gemmae are asexual buds of liverworts.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-35", "question": "Gemmae, by which liverworts reproduce asexually, are:", "options": ["Green, multicellular asexual buds formed in small receptacles called gemma cups", "Haploid spores produced in the capsule", "Diploid buds formed on the sporophyte", "Motile male gametes released from antheridia"], "answer": 0, "explanation": "Gemmae are green, multicellular asexual buds that develop in gemma cups on the thallus, detach and grow into new individuals.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-36", "question": "Sphagnum is used as a packing material for trans-shipment of living material because of its:", "options": ["Antibiotic secretions", "Capacity to hold water", "Rigid lignified tissues", "Ability to fix nitrogen"], "answer": 1, "explanation": "Sphagnum has a high water-holding capacity, so it keeps living material moist in transit; it also provides peat that is used as fuel.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-37", "question": "Euglena is described as a connecting link between plants and animals because it:", "options": ["Has a cellulose cell wall but ingests food", "Reproduces by both spores and gametes", "Is photosynthetic in sunlight but behaves as a heterotroph, predating on smaller organisms, when deprived of light", "Has both chlorophyll and haemoglobin"], "answer": 2, "explanation": "Euglenoids are photosynthetic in light but heterotrophic in darkness. They lack a cell wall; their covering is a flexible protein-rich pellicle.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-38", "question": "The smut fungus Ustilago and the rust fungus Puccinia belong to the class:", "options": ["Phycomycetes", "Ascomycetes", "Deuteromycetes", "Basidiomycetes"], "answer": 3, "explanation": "Ustilago (smut), Puccinia (rust) and Agaricus (mushroom) are basidiomycetes, which form basidiospores exogenously on a basidium.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-39", "question": "The families Felidae and Canidae are placed together in the order:", "options": ["Carnivora", "Primata", "Diptera", "Polymoniales"], "answer": 0, "explanation": "Felidae (cats) and Canidae (dogs) share carnivorous features and form the order Carnivora of class Mammalia. Polymoniales is a plant order containing Solanaceae and Convolvulaceae.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-40", "question": "Sleeping sickness is caused by Trypanosoma, which belongs to the protozoan group:", "options": ["Amoeboid protozoans", "Flagellated protozoans", "Ciliated protozoans", "Sporozoans"], "answer": 1, "explanation": "Trypanosoma is a parasitic flagellated protozoan. Sporozoans such as Plasmodium have an infectious spore-like stage, and ciliates such as Paramoecium have a gullet.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-41", "question": "Which of the following structures is haploid?", "options": ["The capsule wall of a moss", "The nucellus of Pinus", "The prothallus of a fern", "The root of Selaginella"], "answer": 2, "explanation": "The fern prothallus is the free-living gametophyte, formed from a haploid spore. The moss capsule is part of the diploid sporophyte, the Pinus nucellus is sporophytic tissue of the ovule, and the Selaginella root belongs to the sporophyte.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-42", "question": "Which alga shows a haplo-diplontic life cycle, with both multicellular haploid and diploid phases?", "options": ["Volvox", "Spirogyra", "Fucus", "Polysiphonia"], "answer": 3, "explanation": "Polysiphonia, Ectocarpus and kelps are haplo-diplontic. Volvox and Spirogyra are haplontic, and Fucus is diplontic.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-43", "question": "The stored food of brown algae (Phaeophyceae) is:", "options": ["Laminarin or mannitol", "Floridean starch", "Starch", "Glycogen and oil droplets only"], "answer": 0, "explanation": "Phaeophyceae store complex carbohydrates as laminarin or mannitol. Floridean starch is the reserve of red algae, and starch that of green algae.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-44", "question": "Which of the following is NOT a moss?", "options": ["Funaria", "Marchantia", "Sphagnum", "Polytrichum"], "answer": 1, "explanation": "Marchantia is a liverwort with a thalloid, dorsiventral gametophyte. Funaria, Polytrichum and Sphagnum are mosses with a leafy stage.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-45", "question": "In ascomycetes, the asexual spores are:", "options": ["Zoospores produced endogenously in sporangia", "Ascospores produced endogenously in asci", "Conidia produced exogenously on special mycelia called conidiophores", "Basidiospores produced exogenously on basidia"], "answer": 2, "explanation": "Ascomycetes reproduce asexually by conidia borne exogenously on conidiophores; their sexual spores are ascospores formed endogenously in asci.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-46", "question": "A zygospore, a thick-walled resting spore formed by fusion of two gametes, is characteristic of:", "options": ["Deuteromycetes such as Alternaria", "Ascomycetes such as Aspergillus", "Basidiomycetes such as Agaricus", "Phycomycetes such as Mucor and Rhizopus"], "answer": 3, "explanation": "In phycomycetes the gametes fuse to form a zygospore. Ascomycetes form ascospores, basidiomycetes form basidiospores, and deuteromycetes have no known sexual stage.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-47", "question": "Chemosynthetic autotrophic bacteria obtain the energy needed for ATP production by:", "options": ["Oxidising inorganic substances such as nitrates, nitrites and ammonia", "Absorbing light with bacteriochlorophyll", "Fermenting organic matter in the absence of oxygen", "Parasitising other living cells"], "answer": 0, "explanation": "Chemosynthetic bacteria oxidise inorganic substances and use the released energy; they help recycle nitrogen, phosphorus, iron and sulphur.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-48", "question": "In which gymnosperm are the male cones and the female cones borne on the same tree?", "options": ["Cycas", "Pinus", "Both Cycas and Pinus", "Neither Cycas nor Pinus"], "answer": 1, "explanation": "Pinus is monoecious, bearing male and female cones on the same tree. In Cycas the male cones and the megasporophylls are on different trees.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-49", "question": "How many of the following statements about fungi are correct?\n(i) Fungal cell walls are composed of chitin and polysaccharides.\n(ii) Most fungi are heterotrophic and absorb soluble organic matter from dead substrates or living hosts.\n(iii) In all fungi, karyogamy follows plasmogamy immediately.\n(iv) Unicellular fungi such as yeast are used to make bread and beer.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iv) are correct. In ascomycetes and basidiomycetes an intervening dikaryotic stage (n + n) separates plasmogamy from karyogamy, so (iii) is wrong.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-50", "question": "Match the taxonomic category of mango with its rank.\nList I: (A) Anacardiaceae (B) Sapindales (C) Dicotyledonae (D) Angiospermae\nList II: (1) Class (2) Family (3) Division (4) Order", "options": ["A-4, B-2, C-1, D-3", "A-2, B-4, C-1, D-3", "A-2, B-4, C-3, D-1", "A-2, B-1, C-4, D-3"], "answer": 1, "explanation": "Mango (Mangifera indica) is in family Anacardiaceae, order Sapindales, class Dicotyledonae and division Angiospermae. Families end in -aceae and plant orders often in -ales.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-51", "question": "Assertion (A): Mosses are of great ecological importance in plant succession on bare rocks.\nReason (R): Mosses, along with lichens, are among the first organisms to colonise rocks and help decompose them, making the substrate suitable for higher plants.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Mosses and lichens are pioneer colonisers of rocks; by decomposing rock they build substrate for later plants, which is exactly why they matter in succession.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-52", "question": "How many of the following statements about red algae (Rhodophyceae) are correct?\n(i) The red colour is due to the pigment r-phycoerythrin.\n(ii) The majority of red algae are found in fresh water.\n(iii) Sexual reproduction is by motile, flagellated gametes.\n(iv) Some red algae are found at great depths in the sea where relatively little light penetrates.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only (i) and (iv) are correct. Most red algae are marine, with greater concentrations in warmer areas, and their gametes are non-motile; sexual reproduction is oogamous.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-53", "question": "Match the plant with its group.\nList I: (A) Equisetum (B) Ginkgo (C) Riccia (D) Chara\nList II: (1) Bryophyte (2) Pteridophyte (3) Gymnosperm (4) Alga", "options": ["A-2, B-3, C-4, D-1", "A-3, B-2, C-1, D-4", "A-2, B-3, C-1, D-4", "A-1, B-3, C-2, D-4"], "answer": 2, "explanation": "Equisetum (horsetail) is a pteridophyte, Ginkgo a gymnosperm, Riccia a liverwort (bryophyte), and Chara a green alga.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-54", "question": "All of the following produce motile male gametes that need water for fertilisation EXCEPT:", "options": ["Pteris", "Marchantia", "Chlamydomonas", "Pinus"], "answer": 3, "explanation": "In Pinus the non-motile male gametes are carried to the egg by a pollen tube, so water is not needed. Ferns, liverworts and Chlamydomonas have flagellated male gametes that swim through water.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-55", "question": "Assertion (A): A lichen is a symbiotic association between an alga and a fungus.\nReason (R): The algal partner prepares food for the fungus, while the fungus provides shelter and absorbs mineral nutrients and water for its partner.", "options": ["Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "Both A and R are true and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "The mutual benefit described in R, food from the phycobiont and shelter, water and minerals from the mycobiont, is what makes the lichen association symbiotic.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-56", "question": "How many of the following statements about kingdom Protista are correct?\n(i) All single-celled eukaryotes are placed under Protista.\n(ii) Members of Protista are primarily terrestrial.\n(iii) Some protists have flagella or cilia.\n(iv) Sexual reproduction is absent in all protists.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only (i) and (iii) are correct. Protists are primarily aquatic, and they reproduce sexually by a process involving cell fusion and zygote formation.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-57", "question": "The leaf cells of a moss species contain 10 chromosomes each. The chromosome numbers in a cell of its protonema, its seta and one of its spores are, respectively:", "options": ["10, 10, 20", "20, 20, 10", "10, 20, 20", "10, 20, 10"], "answer": 3, "explanation": "The leafy moss is the haploid gametophyte (n = 10), so the protonema has 10. The seta belongs to the diploid sporophyte (2n = 20), and spores formed by meiosis in the capsule are haploid (10).", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-58", "question": "How many of the following statements about the taxonomic hierarchy are correct?\n(i) A genus is a group of related species that have more characters in common than species of other genera.\n(ii) As we go higher from species to kingdom, the number of common characteristics increases.\n(iii) A class is a group of related families.\n(iv) Solanum, Petunia and Datura are placed in the family Convolvulaceae.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 0, "explanation": "Only (i) is correct. Common characters decrease as we go up the hierarchy, a class groups related orders (an order groups families), and Solanum, Petunia and Datura belong to Solanaceae.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-59", "question": "Match the class of pteridophytes with its example.\nList I: (A) Psilopsida (B) Lycopsida (C) Sphenopsida (D) Pteropsida\nList II: (1) Equisetum (2) Psilotum (3) Dryopteris and Adiantum (4) Selaginella and Lycopodium", "options": ["A-2, B-4, C-1, D-3", "A-2, B-1, C-4, D-3", "A-4, B-2, C-1, D-3", "A-2, B-4, C-3, D-1"], "answer": 0, "explanation": "Psilotum is in Psilopsida, Selaginella and Lycopodium in Lycopsida, Equisetum in Sphenopsida, and the ferns Dryopteris, Pteris and Adiantum in Pteropsida.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-living-world-plant-kingdom-60", "question": "How many of the following statements about green algae are correct?\n(i) Pyrenoids located in the chloroplasts contain protein besides starch.\n(ii) Some algae store food in the form of oil droplets.\n(iii) The cell wall has an inner layer of cellulose and an outer layer of pectose.\n(iv) Volvox is colonial, while Ulothrix and Spirogyra are filamentous.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Chlorophyceae store starch in pyrenoids that also contain protein, may store oil, have a cellulose-pectose wall, and range from unicellular and colonial to filamentous forms.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-61","question":"Rhizopus, a common member of the Phycomycetes, is popularly called:","options":["Smut fungus","Bread mould","Rust fungus","Sac fungus"],"answer":1,"explanation":"Rhizopus is the bread mould. Ustilago is the smut fungus and Puccinia the rust fungus, both basidiomycetes; 'sac fungi' is the common name of ascomycetes.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-62","question":"Comma-shaped bacteria are called:","options":["Coccus","Bacillus","Vibrio","Spirillum"],"answer":2,"explanation":"Bacteria are grouped by shape: spherical coccus, rod-shaped bacillus, comma-shaped vibrio and spiral spirillum.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-63","question":"The giant redwood tree, one of the tallest tree species, is the gymnosperm:","options":["Cycas","Pinus","Ginkgo","Sequoia"],"answer":3,"explanation":"Sequoia (giant redwood) is among the tallest trees. Gymnosperms range from medium-sized trees to such tall trees and shrubs.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-64","question":"The order Polymoniales includes the families:","options":["Convolvulaceae and Solanaceae","Felidae and Canidae","Poaceae and Anacardiaceae","Hominidae and Muscidae"],"answer":0,"explanation":"Polymoniales groups Convolvulaceae and Solanaceae mainly on the basis of floral characters. Felidae and Canidae are animal families placed in the order Carnivora.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-65","question":"Which of the following is a defining feature of all living organisms, without any exception?","options":["Growth","Reproduction","Increase in mass","Metabolism"],"answer":3,"explanation":"All living organisms are made of chemicals whose constant making and breaking is metabolism; no non-living object shows it. Growth and reproduction both have exceptions, so neither can define life.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-66","question":"In diatoms, the cell walls:","options":["Are made of chitin and form a single continuous shell","Form two thin overlapping shells that fit together like a soap box and are embedded with silica","Are replaced by a protein-rich pellicle","Are made of stiff cellulose plates with two furrows for flagella"],"answer":1,"explanation":"Diatom walls are two overlapping silica shells, which makes them almost indestructible and builds up diatomaceous earth. A pellicle is found in euglenoids, and cellulose plates in dinoflagellates.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-67","question":"Specialised cells called heterocysts, which fix atmospheric nitrogen, are found in:","options":["Spirogyra and Ulothrix","Mycoplasma","Nostoc and Anabaena","Rhizopus and Mucor"],"answer":2,"explanation":"The cyanobacteria Nostoc and Anabaena fix nitrogen in heterocysts. Spirogyra and Ulothrix are green algae, and Rhizopus and Mucor are fungi.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-68","question":"Morels and truffles, which are edible and considered delicacies, belong to the class:","options":["Phycomycetes","Ascomycetes","Basidiomycetes","Deuteromycetes"],"answer":1,"explanation":"Morels and truffles are sac fungi (Ascomycetes). Mushrooms, which are also edible, are basidiomycetes.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-69","question":"In a lichen, the algal and fungal components are known, respectively, as:","options":["Phycobiont and mycobiont","Mycobiont and phycobiont","Holdfast and frond","Plasmodium and sporangium"],"answer":0,"explanation":"The phycobiont (alga) is autotrophic and makes food, while the mycobiont (fungus) is heterotrophic and gives shelter and absorbs mineral nutrients and water.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-70","question":"W. M. Stanley (1935) showed that viruses could be crystallised. These crystals consist largely of:","options":["Lipids","Carbohydrates","Proteins","DNA only"],"answer":2,"explanation":"Stanley found that viral crystals are mostly protein. Outside their specific host cells, viruses are inert.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-71","question":"The zoospores of brown algae (Phaeophyceae) are:","options":["Spherical, with 2 to 8 equal apical flagella","Pear-shaped, with two unequal laterally attached flagella","Non-motile, without flagella","Oval, with a single long anterior flagellum"],"answer":1,"explanation":"Brown algal zoospores are pear-shaped with two unequal lateral flagella. Green algae have 2 to 8 equal apical flagella, and red algae have no flagella.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-72","question":"Small leaves (microphylls) are found in the pteridophyte:","options":["Selaginella","Dryopteris","Pteris","Adiantum"],"answer":0,"explanation":"Selaginella has microphylls. Ferns such as Dryopteris, Pteris and Adiantum have large leaves (macrophylls).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-73","question":"In mosses, vegetative reproduction by fragmentation and budding takes place in the:","options":["Capsule","Seta","Leafy gametophyte only","Secondary protonema"],"answer":3,"explanation":"Mosses reproduce vegetatively by fragmentation and budding in the secondary protonema. The capsule and seta are parts of the sporophyte and produce spores, not vegetative buds.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-74","question":"In green algae (Chlorophyceae), the cell wall consists of:","options":["An inner layer of cellulose and an outer layer of pectose","Cellulose covered on the outside by a gelatinous coating of algin","Cellulose, pectin and polysulphate esters","Silica in two overlapping halves"],"answer":0,"explanation":"Green algae have an inner cellulose layer and an outer pectose layer. An algin coat is found in brown algae, polysulphate esters in red algae, and silica walls in diatoms.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-75","question":"Porphyra, Laminaria and Sargassum are among the marine algae used as food. About how many species of marine algae are used as food?","options":["7","70","700","7,000"],"answer":1,"explanation":"About 70 species of marine algae are used as food. Algae also carry out at least half of the total carbon dioxide fixation on Earth.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-76","question":"Which of the following plant diseases is caused by a bacterium?","options":["Wheat rust","Tobacco mosaic disease","Potato spindle tuber disease","Citrus canker"],"answer":3,"explanation":"Citrus canker is bacterial, like cholera, typhoid and tetanus in humans. Wheat rust is caused by the fungus Puccinia, tobacco mosaic by a virus and potato spindle tuber by a viroid.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-77","question":"In gymnosperms, the megaspore mother cell is differentiated from:","options":["One of the cells of the nucellus","The integument","A cell of the pollen tube","The archegonium"],"answer":0,"explanation":"The megaspore mother cell arises from one nucellar cell. The nucellus, protected by envelopes, forms the ovule, which later develops into the seed.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-78","question":"Which member of kingdom Plantae is a parasite?","options":["Bladderwort","Venus fly trap","Sphagnum","Cuscuta"],"answer":3,"explanation":"Cuscuta is a parasitic plant. Bladderwort and Venus fly trap are insectivorous plants, which are also partially heterotrophic, and Sphagnum is a moss.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-79","question":"Which pair consists of two different species of the same genus?","options":["Lion and leopard","Lion and cat","Potato and mango","Tiger and dog"],"answer":0,"explanation":"Lion (Panthera leo) and leopard (Panthera pardus) are both in Panthera. The cat (Felis) is in the same family Felidae but in a different genus, and the dog is in Canidae.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-80","question":"Match the type of classification with its basis.\nList I: (A) Numerical taxonomy (B) Cytotaxonomy (C) Chemotaxonomy (D) Artificial system of Linnaeus\nList II: (1) Chemical constituents of the plant (2) Chromosome number, structure and behaviour (3) All observable characters, coded and given equal importance, using computers (4) A few vegetative characters or the androecium structure","options":["A-3, B-1, C-2, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-1, D-4","A-4, B-2, C-1, D-3"],"answer":2,"explanation":"Numerical taxonomy analyses all observable characters by computer, cytotaxonomy uses chromosomes, chemotaxonomy uses chemical constituents, and Linnaeus's artificial system used only a few characters.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-81","question":"Match the alga with its type of sexual reproduction.\nList I: (A) Spirogyra (B) Ulothrix (C) Some species of Chlamydomonas (D) Fucus\nList II: (1) Oogamous (2) Anisogamous (3) Isogamous, with non-flagellated gametes (4) Isogamous, with flagellated gametes","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1"],"answer":3,"explanation":"Spirogyra fuses non-motile gametes of equal size, while Ulothrix fuses flagellated gametes of equal size. Some species of Chlamydomonas fuse unequal gametes (anisogamy), and Fucus, like Volvox, is oogamous.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-82","question":"From the following, how many kinds of spores are produced ENDOGENOUSLY?\nZoospores of Phycomycetes, aplanospores of Phycomycetes, conidia of Ascomycetes, ascospores, basidiospores","options":["One","Two","Three","Four"],"answer":2,"explanation":"Zoospores and aplanospores form inside sporangia, and ascospores inside asci, so all three are endogenous. Conidia form on conidiophores and basidiospores on the basidium, so both are exogenous.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-83","question":"How many of the following statements about fungi are correct?\n(i) The sexual cycle involves plasmogamy, karyogamy and meiosis.\n(ii) In ascomycetes and basidiomycetes, a dikaryotic (n + n) stage occurs between plasmogamy and karyogamy.\n(iii) In basidiomycetes, karyogamy and meiosis take place in the basidium, which produces four basidiospores.\n(iv) Phycomycetes have a septate mycelium.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. The Phycomycetes mycelium is aseptate and coenocytic.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-84","question":"From the following list, how many are symptoms of viral infection in plants?\nMosaic formation, leaf rolling and curling, yellowing and vein clearing, dwarfing and stunted growth, root nodule formation, black powdery smut masses","options":["Three","Five","Four","Six"],"answer":2,"explanation":"The first four are viral symptoms in plants. Root nodules are formed with Rhizobium, and black powdery smut masses are caused by the smut fungus Ustilago.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-85","question":"From the following, how many are criteria Whittaker used for his five-kingdom classification?\nCell structure, body organisation, mode of nutrition, reproduction, phylogenetic relationships, chromosome number, presence of flagella","options":["Three","Four","Five","Six"],"answer":2,"explanation":"Whittaker used cell structure, body (thallus) organisation, mode of nutrition, reproduction and phylogenetic relationships. Chromosome number and flagella were not among his criteria.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-86","question":"How many of the following statements about gymnosperms are correct?\n(i) The ovules are not enclosed by an ovary wall and stay exposed before and after fertilisation.\n(ii) The needle-like leaves of conifers reduce surface area, and their thick cuticle and sunken stomata reduce water loss.\n(iii) The male gametophyte is highly reduced, to a limited number of cells within the pollen grain.\n(iv) The female gametophyte bears two or more archegonia.\n(v) The stem of Cycas is much branched.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"Statements (i) to (iv) are correct. The stem of Cycas is unbranched, whereas Pinus and Cedrus have branched stems.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-87","question":"Assertion (A): Reproduction cannot be taken as an all-inclusive defining characteristic of living organisms.\nReason (R): Many organisms, such as mules, sterile worker bees and infertile human couples, do not reproduce.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. Because many living organisms never reproduce, reproduction cannot define life; R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-88","question":"Assertion (A): Increase in mass cannot be taken as a defining property of living organisms.\nReason (R): Living organisms grow by the accumulation of material on their outer surface.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true, because mountains, boulders and sand mounds also gain mass. R is false: non-living objects grow by accumulation on the surface, whereas living organisms grow from inside.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-89","question":"Assertion (A): Isolated metabolic reactions carried out in a test tube (in vitro) are not living things, although they are living reactions.\nReason (R): Cellular organisation of the body is the defining feature of life forms.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. An isolated reaction is not alive because it lacks cellular organisation, which is the defining feature of life; so R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-living-world-plant-kingdom-90","question":"In dinoflagellates, the two flagella:","options":["Are both apical and equal in length","Lie one longitudinally and the other transversely, in a furrow between the wall plates","Are both attached laterally and are unequal, as in brown algae","Are absent; the cells glide using a pellicle"],"answer":1,"explanation":"Dinoflagellates have stiff cellulose plates on the outer surface, and of their two flagella one lies longitudinally and the other transversely in a furrow between the plates. Euglenoids, not dinoflagellates, have a pellicle.","difficulty":"hard","source":"NEET pattern"},
];

export default questions;
